    private val byDisplay=rows.associateBy { it.display }
    private val byDiagnostic=rows.associateBy { it.diagnostic }
    init { require(byDisplay.size==rows.size && byDiagnostic.size==rows.size) }
    fun lookup(code:String):DisplayLookup? {
        val row=byDisplay[code] ?: byDiagnostic[code] ?: return null
        return DisplayLookup("ELEX · "+row.component,row.condition,
            (if(row.page<=31) OEM+" · раздел 11; сверено с " else "WABCO 8150101383, 12.2018 · ")+COPY+"#page="+row.page+" · "+row.display+" / "+row.diagnostic,true)
    }
    val count get()=rows.size
}
